// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    MultiplicatorX3 c;
    function setUp() public { c = new MultiplicatorX3(); }
    function testFuzz_property(address adr, bytes memory data, uint256 amount) public {
        vm.assume(adr != address(c) && adr != address(0));
        amount = bound(amount, 0, 1e36);
        vm.deal(address(c), amount);
        vm.deal(address(this), amount);

        uint256 balBefore = adr.balance;
        vm.prank(address(this));
        c.Command{value: amount}(adr, data);
        uint256 balAfter = adr.balance;

        assertTrue(balAfter == balBefore + amount);
    }
}
